begin;
select plan(38);
select has_table('private','native_production_correction_reports','Signed transaction manifests are persisted');
select has_table('private','native_production_correction_components','Stable signed components are retained');
select has_table('private','native_production_correction_checkpoints','Cumulative accounted target is immutable');
select has_table('private','native_production_credit_sources','Native credits retain a dedicated domain');
select has_table('private','native_production_corrected_openings','Positive corrected opening has explicit provenance');
select has_table('private','native_production_corrected_funding_proofs','Corrected liability funding is a distinct proof');
select has_function('private','append_native_production_correction',array['uuid','jsonb'],'Report adapter is private');
select has_function('private','evaluate_native_production_correction',array['uuid'],'Current signed target is evaluated');
select has_function('private','native_production_unpaid_liability',array['uuid'],'Actual unpaid liability is computed independently of debt');
select has_function('private','native_production_negative_manifest',array['uuid'],'Exact negative identities are covered');
select has_function('private','native_production_credit_integrity',array['uuid'],'Native credit integrity is explicit');
select has_function('private','native_production_corrected_funding_current',array['uuid','bigint'],'Current corrected funding binds checkpoint and liability');
select is((select account_corrections from private.native_production_earning_controls where singleton),false,'Corrections default OFF');
select is((select release_correction_credits from private.native_production_earning_controls where singleton),false,'Credit release defaults OFF');
select ok(not has_function_privilege('service_role','private.append_native_production_correction(uuid,jsonb)','EXECUTE'),'Service JSON cannot issue actual provider evidence');
select ok(not has_table_privilege('service_role','private.native_production_correction_qualifications','INSERT,UPDATE,DELETE,TRUNCATE'),'API cannot qualify provider semantics');
select ok(not has_table_privilege('authenticated','private.native_production_credit_sources','INSERT,UPDATE,DELETE,TRUNCATE'),'Client cannot create a native credit link');
select ok(not has_function_privilege('service_role','private.reconcile_native_production_before_corrections(uuid)','EXECUTE'),'Old materializer cannot bypass current corrections');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where relnamespace='private'::regnamespace
 and relname in ('native_production_correction_reports','native_production_correction_components','native_production_correction_checkpoints','native_production_credit_sources','native_production_corrected_openings','native_production_corrected_funding_proofs')),'All correction authority tables force RLS');
select is((select count(*)::integer from private.native_production_correction_qualifications),0,'No fabricated provider qualification is seeded');
select has_table('private','native_production_liability_history','Paid and returned allocation history cannot disappear');
select has_function('private','native_production_global_usd_liability',array[]::text[],'Single-account funding covers every competing USD creator liability');
select has_function('private','native_production_negative_financial_facts',array['uuid'],'Known negative financial facts are compared to correction components');
select ok(not has_table_privilege('service_role','private.native_production_liability_history','INSERT,UPDATE,DELETE,TRUNCATE'),'Payment history cannot be forged through API');
select ok(not has_function_privilege('service_role','private.native_production_global_usd_liability()','EXECUTE'),'Global funding qualification stays private');
select has_table('private','native_production_liability_generation','Every enabled liability change advances trusted monotonic generation');
select has_table('private','native_production_liability_snapshots','Current qualification uses bounded generation cache');
select has_column('private','native_production_corrected_funding_proofs','liability_generation','Funding proof binds exact generation');
select ok(not has_function_privilege('service_role','private.capture_native_production_global_liability(uuid)','EXECUTE'),'Only separately trusted funding issuer can capture a pool snapshot');
select has_table('private','native_production_liability_capture_failures','Construction overflow and provenance holds have bounded diagnostics');
select has_function('private','capture_native_production_global_liability_bounded',array['uuid','integer','integer'],'Private construction budgets can only be narrowed');
select ok(not has_function_privilege('service_role','private.capture_native_production_global_liability_bounded(uuid,integer,integer)','EXECUTE'),'API cannot change the capture budget or create snapshots');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.native_production_liability_capture_failures'::regclass),'Diagnostic table also forces RLS');
select has_function('private','native_production_policy_deadline',array['timestamp with time zone','interval'],'Native policy deadlines use a narrowly scoped UTC calculation');
select ok(not has_function_privilege('service_role','private.native_production_policy_deadline(timestamptz,interval)','EXECUTE'),'Native policy arithmetic is not an API authority');
set local timezone='America/Los_Angeles';
select is(private.native_production_policy_deadline('2025-10-15T12:00:00Z',interval '37 days'),'2025-11-21T12:00:00Z'::timestamptz,'DST does not alter the retained UTC reserve period');
select is(current_setting('TimeZone'),'America/Los_Angeles','Native calculation restores caller timezone');
select ok(not exists(select 1 from pg_proc p,unnest(p.proconfig) setting where p.oid='public.reconcile_native_production_earning(uuid)'::regprocedure and lower(setting) like 'timezone=%'),'Public reconciliation does not change nested legacy-domain timezone');
select * from finish();
rollback;
